//! 🧪️ Neutral story flow and addressed frame replay preserve exact UTF-8 placement and one analysis per thread.
use super::*;
use serde_json::Value;
use semio_s_artifact_layout_layout_model::{LayoutBounds,LayoutRect};
fn number(row:&Value,key:&str)->f64{row[key].as_f64().unwrap()}
fn frames(row:&Value)->Vec<FlowFrame>{row["frames"].as_array().unwrap().iter().map(|value|FlowFrame{page_index:value["pageIndex"].as_u64().unwrap()as usize,frame_index:value["frameIndex"].as_u64().unwrap()as usize,parent:value["parent"].as_bool().unwrap(),story_index:0,next:value["next"].as_u64().map(|n|n as usize),columns:value["columns"].as_u64().unwrap()as u32,gutter:number(value,"gutter"),bounds:super::super::super::text_flow::FlowBounds{x:number(&value["bounds"],"x"),y:number(&value["bounds"],"y"),width:number(&value["bounds"],"width"),height:number(&value["bounds"],"height"),rotation:number(&value["bounds"],"rotation")},inset:super::super::super::text_flow::FlowRect{x:number(&value["inset"],"x"),y:number(&value["inset"],"y"),width:number(&value["inset"],"width"),height:number(&value["inset"],"height")}}).collect()}
fn document(row:&Value)->LayoutSnapshot{let mut doc=semio_s_artifact_layout_layout_model::io::text::snapshot::snapshot_wire_codec::default_document();doc.stories[0].content=row["text"].as_str().unwrap().into();doc.stories[0].style_runs.clear();doc.paragraph_styles[0].font_family="Share Tech Mono".into();doc.paragraph_styles[0].font_size=12.0;doc.paragraph_styles[0].leading=16.0;doc.paragraph_styles[0].tracking=0.0;doc.paragraph_styles[0].alignment="left".into();doc}
fn prepare(state:&mut LayoutParagraphState,doc:&LayoutSnapshot){for _ in 0..100000{if state.flow_projection_ready(){return;}let d=state.flow_projection_demand(doc).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};state.prepare_flow_projection(doc,grant).unwrap();}panic!("flow projection did not terminate");}
#[test]fn portable_story_flow_matches_selected_font_metrics(){let fixture:Value=serde_json::from_str(include_str!("../🧫️fixtures/🧵️flow.json")).unwrap();let mut state=LayoutParagraphState::new();for row in fixture["cases"].as_array().unwrap(){let doc=document(row);let frames=frames(row);let source=state.owners.plans.len();state.begin_story_flow(&doc,0,0).unwrap();let mut emitted=Vec::new();let mut complete=false;for _ in 0..1000000{match state.advance_flow_funded(&doc,frames.as_slice(),original_font_grant()).unwrap(){LayoutParagraphTurn::Glyph(glyph)=>emitted.push(glyph),LayoutParagraphTurn::Complete=>{complete=true;break;},LayoutParagraphTurn::Pending=>{}}}assert!(complete);assert_eq!(state.line_count(source).unwrap(),row["lines"].as_array().unwrap().len());let mut at=0;for (line_index,expected) in row["lines"].as_array().unwrap().iter().enumerate(){let line=state.line(source,line_index).unwrap().unwrap();assert_eq!(line.start,expected["start"].as_u64().unwrap()as usize);assert_eq!(line.end,expected["end"].as_u64().unwrap()as usize);let mut x=expected["origin"][0].as_f64().unwrap();let y=expected["origin"][1].as_f64().unwrap()+12.0;for scalar in expected["text"].as_str().unwrap().chars(){let published=emitted[at];let glyph=state.glyph(source,published.glyph).unwrap();let font=ttf_parser::Face::parse(export_font_source(glyph.face).unwrap(),0).unwrap();let oracle=font.glyph_index(scalar).unwrap();assert_eq!(glyph.glyph,oracle.0);assert!((glyph.origin[0]-x).abs()<0.000001);assert!((glyph.origin[1]-y).abs()<0.000001);let region=state.glyph_region(source,published.glyph).unwrap().unwrap();let frame=frames[region.frame];assert_eq!(region.page_index,frame.page_index);assert_eq!(region.frame_index,frame.frame_index);assert_eq!(region.parent,frame.parent);assert_eq!(published.rotation,frame.bounds.rotation as f32);x+=f64::from(font.glyph_hor_advance(oracle).unwrap())*12.0/f64::from(font.units_per_em());at+=1;}}assert_eq!(at,emitted.len());assert_eq!(state.flow_overset(source).unwrap(),row["name"]=="Explicit Overset Prefix");}retire(state);}
#[test]fn addressed_frames_reuse_one_story_in_arbitrary_page_order(){let fixture:Value=serde_json::from_str(include_str!("../🧫️fixtures/🧵️flow.json")).unwrap();let requests:Value=serde_json::from_str(include_str!("../🧫️fixtures/📇️addressed.json")).unwrap();for test in requests["cases"].as_array().unwrap(){let row=&fixture["cases"][test["flow"].as_u64().unwrap()as usize];let source_frames=frames(row);let mut doc=document(row);let template=doc.pages[0].clone();doc.pages.clear();doc.parent_pages.clear();for page_index in 0..=source_frames.iter().map(|f|f.page_index).max().unwrap(){let mut page=template.clone();page.id=format!("flow-page-{page_index}");page.parent_page_id=None;page.frames.clear();page.overrides.clear();doc.pages.push(page);}let mut addresses=Vec::new();for (at,source) in source_frames.iter().enumerate(){let page=&mut doc.pages[source.page_index];page.columns.gutter=source.gutter;let frame_index=page.frames.len();addresses.push((source.page_index,frame_index));page.frames.push(Frame::Text{id:format!("flow-frame-{at}"),layer_id:page.layers[0].id.clone(),bounds:LayoutBounds{x:source.bounds.x,y:source.bounds.y,width:source.bounds.width,height:source.bounds.height,rotation:source.bounds.rotation},locked:None,visible:None,story_id:doc.stories[0].id.clone(),thread_next:source.next.map(|next|format!("flow-frame-{next}")),columns:source.columns,inset:LayoutRect{x:source.inset.x,y:source.inset.y,width:source.inset.width,height:source.inset.height},wrap_mode:"none".into()});}let mut state=LayoutParagraphState::new();prepare(&mut state,&doc);for (request,frame) in test["requests"].as_array().unwrap().iter().enumerate(){let (page,frame)=addresses[frame.as_u64().unwrap()as usize];state.begin_addressed_frame(&doc,page,false,frame).unwrap();let mut actual=String::new();let mut glyphs=0;let mut steps=0;for _ in 0..1000000{steps+=1;match state.advance_one_funded(&doc,original_font_grant()).unwrap(){LayoutParagraphTurn::Glyph(glyph)=>{let cluster=state.glyph_cluster(&doc,glyph.source,glyph.glyph).unwrap();if cluster.first_glyph{actual.push_str(cluster.text);}glyphs+=1;},LayoutParagraphTurn::Complete=>break,LayoutParagraphTurn::Pending=>{}}}assert_eq!(actual,test["expected"][request].as_str().unwrap());assert_eq!(state.owners.plans.len(),1);if request>0{assert!(steps<=glyphs+2);}}let changed=doc.clone();let (page,frame)=addresses[0];assert!(state.begin_addressed_frame(&changed,page,false,frame).is_err());retire(state);}}
